static JNIEXPORT void JNICALL rc_AWT_swapBuffers_0(JNIEnv *env, jobject self)
{
    static int once = 0; if (!once) { once = 1;
        rc_trace([NSString stringWithFormat:@"[routec] first swapBuffers thread=%p fbo=%dx%d present=%d",
            (void *)pthread_self(), [RouteCBridge fbWidth], [RouteCBridge fbHeight], (int)[RouteCBridge isPresenting]]); }

    if ([RouteCBridge isPresenting]) {
        // Direct present: scan the drawable out to the CAEAGLLayer — no glReadPixels, no int[] blit, no CGImage.
        double p0 = rc_now_seconds();
        [RouteCBridge present];
        double tPresent = rc_now_seconds() - p0;
        static int frames = 0; static double accPresent = 0, lastLog = 0;
        double now = rc_now_seconds();
        frames++; accPresent += tPresent;
        if (lastLog == 0) lastLog = now;
        double span = now - lastLog;
        if (span >= 1.0) {
            rc_trace([NSString stringWithFormat:@"[perf] engine=%.1f fps  present=%.2f ms  (%d frames, %dx%d)",
                frames / span, (accPresent / frames) * 1000.0, frames, [RouteCBridge fbWidth], [RouteCBridge fbHeight]]);
            frames = 0; accPresent = 0; lastLog = now;
        }
    } else {
        rc_swap_publish(env); /* readback fallback (L1 probe / CPU): glReadPixels FBO -> JavaBridge -> publish */
    }
}

static jobject rc_make_caps(JNIEnv *env)
{
    jclass c = (*env)->FindClass(env, "org/lwjgl/opengl/GLCapabilities");
    jmethodID ctor = (*env)->GetMethodID(env, c, "<init>", "()V");
    jobject o = (*env)->NewObject(env, c, ctor);
    (*env)->SetBooleanField(env, o, (*env)->GetFieldID(env, c, "OpenGL33", "Z"), JNI_TRUE);
    (*env)->SetBooleanField(env, o, (*env)->GetFieldID(env, c, "OpenGL45", "Z"), JNI_FALSE);
    (*env)->SetLongField(env, o, (*env)->GetFieldID(env, c, "glTexStorage3D", "J"), 1);
    (*env)->SetLongField(env, o, (*env)->GetFieldID(env, c, "glDebugMessageControl", "J"), 0);
    jboolean aniso = rc_gl_has_ext("GL_EXT_texture_filter_anisotropic") ? JNI_TRUE : JNI_FALSE;
    (*env)->SetBooleanField(env, o, (*env)->GetFieldID(env, c, "GL_EXT_texture_filter_anisotropic", "Z"), aniso);
    return o;
}
static JNIEXPORT jobject JNICALL rc_GL_createCapabilities_0(JNIEnv *env, jclass cls) { rc_trace(@"[routec] GL.createCapabilities (past createGLContext; OpenGL33=true returned)"); return rc_make_caps(env); }
static JNIEXPORT jobject JNICALL rc_GL_getCapabilities_0(JNIEnv *env, jclass cls) { return rc_make_caps(env); }

